from pathlib import Path
import re

root = Path(__file__).parent
text = (root / 'metadata-package-v6-first-person.md').read_text(encoding='utf-8')
text = text.replace('версия от первого лица', 'расширенная версия от первого лица')
additional = {
    1: 'Отдельно остановлюсь на роли Владимира Мединского в переговорах и на том, как присутствие или отсутствие европейских представителей повлияло на обсуждение. Сопоставлю заявления о поражении НАТО с поставками вооружений и участием иностранных инструкторов.\n\nОбъясню, почему, по моему мнению, нынешнее состояние российской армии, усталость военнослужащих и экономические трудности необходимо учитывать, когда звучат разговоры о большой войне с НАТО. В конце обсудим, к чему может привести ядерный сценарий и почему прекращение войны остаётся важнейшим вопросом.',
    2: 'Вспомним, почему часть академического сообщества выступила против передачи научных институтов под управление Курчатовского центра и какую позицию занимал Роберт Искандерович. Поговорим о роли Михаила Ковальчука и о том, как развивается дискуссия о будущем Российской академии наук.\n\nРазберу публикацию об Институте океанологии имени Ширшова и последующие материалы в Telegram. Поделюсь тем, почему меня тревожит не только тон этих публикаций, но и возможные последствия для человека, который открыто критикует решения власти.',
    3: 'Автор обращения рассказывает о погибших и раненых, повреждённых домах и трудностях передвижения по приграничью. По её словам, людям приходится жить под угрозой атак дронов, а обычные повседневные дела и даже прощание с близкими стали опасными.\n\nВ своём комментарии я остановлюсь на её просьбе о помощи жителям Белгородской области и на фразе о том, что они не соглашались становиться щитом. Поговорим о праве граждан быть услышанными и о том, почему люди решаются записывать такие обращения.',
    4: 'Рассуждаю о том, почему в нынешних условиях общественным организациям трудно превращаться в самостоятельную политическую силу. Также затрону ограничения публичных акций и то, как, на мой взгляд, действуют парламентские партии.\n\nВ качестве исторической аналогии вспоминаю события февраля 1917 года: социальное недовольство, реакцию властей и последовавшее отречение Николая II. Затем объясняю своё предположение о том, какую роль в случае неожиданного кризиса могут сыграть представители нынешних элит.',
    5: 'Обсуждаем сообщение о мужчине, которого доставили в военкомат во время прогулки с собакой, и вопросы к проведению призывных мероприятий. Затем переходим к заявлениям Александра Дугина, словам Валерия Фадеева о публичной дискуссии и тому, можно ли требовать от людей молчать, если они не согласны с происходящим.\n\nПавел задаёт мне вопросы о моей позиции по СВО и критике решений власти. Также говорим о военном руководстве, коррупционных расследованиях, состоянии бюджета и переговорах. В заключительной части беседы обсуждаем международные перемены, Октябрьскую революцию и разные оценки Николая II.',
    6: 'В выступлении Роберт Искандерович говорит о низких доходах, естественной убыли населения, инфляции и темпах роста ВВП. Он предлагает показатели для сравнения эффективности инвестиций и рассматривает примеры России, Китая, Польши и США.\n\nКроме того, академик затрагивает состояние промышленности и науки, стоимость энергии и сырья, налогообложение и положение малого предпринимательства. В конце я поделюсь своим взглядом на сказанное и объясню, почему иначе оцениваю ответственность всей вертикали власти.',
    7: 'Роберт Искандерович объясняет, как малочисленное поколение, родившееся в 1990-е годы, влияет на число рождений сегодня. Обсуждаем и экономическую сторону вопроса: зарплаты, доходы семей и возможность решиться на второго ребёнка.\n\nЗатронем смертность, последствия пандемии, доступность медицинской помощи и изменения в здравоохранении. В конце поговорим о том, почему рождаемость снижается и в Европе, какую роль играют образование и возраст рождения детей и какую поддержку семей предлагает академик.',
}
parts = re.split(r'(?=^## \d+\. )', text, flags=re.M)
assert len(parts) == 8
for number in range(1, 8):
    chunk = parts[number]
    assert chunk.count('\nТаймкоды:') == 1
    chunk = chunk.replace('\nТаймкоды:', '\n' + additional[number] + '\n\nТаймкоды:', 1)
    parts[number] = chunk

out = ''.join(parts)
target = root / 'metadata-package-v7-expanded.md'
target.write_text(out, encoding='utf-8')
links = ['🌐 Свободный доступ к интернету:', '🔒 Расследования, инсайды, общение:', '💬 Следить за новостями:']
for number, chunk in enumerate(parts[1:], 1):
    desc = chunk.split('\n', 2)[2].lstrip().split('\n\n**Отдельное поле Tags:**')[0].strip()
    assert all(desc.count(link) == 1 for link in links), number
    assert desc.index(links[0]) < desc.index(links[1]) < desc.index(links[2]), number
    assert '#ДмитрийБорисенко' in desc and '#Борисенко' in desc, number
    assert 'Резервный канал' not in desc and 'Друзья,' not in desc, number
    assert len(desc.encode('utf-8')) < 5000, number
    if number == 6:
        assert desc.startswith('Сайт Московского экономического форума:'), number
    else:
        assert desc.startswith(links[0]), number
    print(number, len(desc.encode('utf-8')), 'bytes, OK')
